from pathlib import Path
p=Path('index.html')
s=p.read_text()

s=s.replace('            --app-height: 100dvh;\n            --app-top: 0px;','            --app-height: 100dvh;\n            --keyboard-height: 0px;',1)
s=s.replace('            height: var(--app-height);','            height: 100dvh;',1)
s=s.replace('            padding: 24px clamp(16px, 3vw, 48px);','            padding: 24px clamp(16px, 3vw, 48px);\n            padding-bottom: calc(24px + var(--keyboard-height));',1)
s=s.replace('            gap: 12px;\n        }\n        #input-msg', '            gap: 12px;\n            transform: translateY(calc(-1 * var(--keyboard-height)));\n            will-change: transform;\n        }\n        #input-msg',1)

start=s.index('    <script>\n        (function() {')
end=s.index('    </script>', start)+len('    </script>')
new_script='''    <script>\n        (function() {\n            const root = document.documentElement;\n            const input = document.getElementById('input-msg');\n            const messages = document.getElementById('chat-messages');\n            let raf = 0;\n            let baseHeight = window.innerHeight;\n            let lastKeyboardHeight = -1;\n\n            function isInputFocused() {\n                return document.activeElement === input;\n            }\n\n            function measure() {\n                raf = 0;\n                const vv = window.visualViewport;\n                const visibleHeight = vv ? vv.height : window.innerHeight;\n\n                if (!isInputFocused()) {\n                    baseHeight = Math.max(window.innerHeight, visibleHeight);\n                }\n\n                let keyboardHeight = 0;\n                if (isInputFocused()) {\n                    keyboardHeight = Math.max(0, Math.round(baseHeight - visibleHeight));\n                    if (keyboardHeight < 120) keyboardHeight = 0;\n                }\n\n                if (keyboardHeight === lastKeyboardHeight) return;\n\n                const bottomGap = messages\n                    ? Math.max(0, messages.scrollHeight - messages.scrollTop - messages.clientHeight)\n                    : 0;\n                const keepAtBottom = bottomGap < 96;\n\n                lastKeyboardHeight = keyboardHeight;\n                root.style.setProperty('--keyboard-height', `${keyboardHeight}px`);\n\n                if (messages && keepAtBottom) {\n                    requestAnimationFrame(function() {\n                        messages.scrollTop = Math.max(0, messages.scrollHeight - messages.clientHeight - bottomGap);\n                    });\n                }\n            }\n\n            function schedule() {\n                if (raf) return;\n                raf = requestAnimationFrame(measure);\n            }\n\n            window.addEventListener('resize', schedule, { passive: true });\n            window.addEventListener('orientationchange', function() {\n                baseHeight = window.innerHeight;\n                schedule();\n            }, { passive: true });\n\n            if (window.visualViewport) {\n                window.visualViewport.addEventListener('resize', schedule, { passive: true });\n                window.visualViewport.addEventListener('scroll', schedule, { passive: true });\n            }\n\n            input.addEventListener('focus', function() {\n                baseHeight = Math.max(baseHeight, window.innerHeight, window.visualViewport ? window.visualViewport.height : 0);\n                schedule();\n            });\n\n            input.addEventListener('blur', function() {\n                lastKeyboardHeight = 0;\n                root.style.setProperty('--keyboard-height', '0px');\n                requestAnimationFrame(function() {\n                    baseHeight = window.innerHeight;\n                });\n            });\n\n            measure();\n        })();\n    </script>'''
s=s[:start]+new_script+s[end:]
s=s.replace('20260815-v22-ios-offset-fix','20260815-v23-keyboard-inset',1)
p.write_text(s)
